@spec tm_fx_gating_spec  src=tests/specs/tm_fx_gating_spec.lua  loc=99  cases=3
@exercises trackerManager (h.tm), midiManager (h.fm)
@surface   tm:fxCurveAt, tm:addEvent, tm:flush, tm:getChannel, tm:assignEvent, fm:dump
@harness   mk

# Intent
  Phase A of the dirt spine (design/archive/dirty-channels.md § Scheme): a clean fx channel freezes and its
  derived notes/CCs/pb seats stand in mm; here a channel frozen by another channel's edit keeps its pb seat stream byte-identical and hidden.

# Helpers
  @fn pbSeatsOf(dump, chan)  @ 8-17
  @fn vibHost(chan)  @ 19-22
  @fn plainNote(chan, ppq)  @ 24-27
  @fn curveAt(h, chan, target, ppqs)  @ 30-34
      -- The chain's realised curve sampled at each of a row's ppqs, as the ghost display reads it.

# Cases
  @case 'fxCurveAt: a chain\'s pb curve samples back in the column\'s units, inside its window only'  [harness]  @ 38-54
  @case 'fxCurveAt: a kept producer\'s curve stands, because it reads the take not the emission'  [harness]  @ 58-76
  @case 'gating: a chan-1 edit freezes chan 2 fx and keeps its pb seat stream'  [harness]  @ 80-97

# Uses (outbound edges)
  @use call tm:fxCurveAt  @ 32,51,52,53
  @use call tm:addEvent  @ 41,61,62,83,84,91,92
  @use call tm:flush  @ 41,61,62,73,83,84,91,92
  @use call tm:getChannel  @ 70,94
  @use call tm:assignEvent  @ 73
  @use call fm:dump  @ 86,95

